import{_ as d,o as r,c as a,a2 as e}from"./chunks/framework.BbQrW5_t.js";const c=JSON.parse('{"title":"AI Agent 实战 - 知识笔记","description":"","frontmatter":{},"headers":[],"relativePath":"study/ai-agent-book/index.md","filePath":"study/ai-agent-book/index.md","lastUpdated":1785465991000}'),o={name:"study/ai-agent-book/index.md"};function h(n,t,s,l,i,g){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="ai-agent-实战-知识笔记" tabindex="-1">AI Agent 实战 - 知识笔记 <a class="header-anchor" href="#ai-agent-实战-知识笔记" aria-label="Permalink to &quot;AI Agent 实战 - 知识笔记&quot;">​</a></h1><blockquote><p>来源：《AI Agent 实战》by Pine AI 团队 开源地址：<a href="https://github.com/bojieli/ai-agent-book" target="_blank" rel="noreferrer">https://github.com/bojieli/ai-agent-book</a> 知识笔记整理：2026年7月</p></blockquote><hr><h2 id="核心公式" tabindex="-1">核心公式 <a class="header-anchor" href="#核心公式" aria-label="Permalink to &quot;核心公式&quot;">​</a></h2><p><strong>Agent = LLM + 上下文 + 工具</strong></p><table tabindex="0"><thead><tr><th>层面</th><th>组成</th><th>类比</th></tr></thead><tbody><tr><td>实现层</td><td>LLM + 上下文 + 工具</td><td>-</td></tr><tr><td>直觉层</td><td>大脑 + 眼睛 + 手脚</td><td>思考 + 感知 + 执行</td></tr><tr><td>学术层</td><td>Policy + Observation Space + Action Space</td><td>策略 + 观察空间 + 动作空间</td></tr></tbody></table><hr><h2 id="全书结构" tabindex="-1">全书结构 <a class="header-anchor" href="#全书结构" aria-label="Permalink to &quot;全书结构&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层次</th><th>章节</th><th>内容</th><th>笔记链接</th></tr></thead><tbody><tr><td><strong>基础</strong></td><td>引言</td><td>核心公式、全书框架、阅读路径</td><td><a href="./00-introduction.html">00-introduction.md</a></td></tr><tr><td><strong>基础</strong></td><td>第一章</td><td>Agent 基础知识、ReAct 循环、编排设计</td><td><a href="./01-chapter1.html">01-chapter1.md</a></td></tr><tr><td><strong>构建</strong></td><td>第二章</td><td>上下文工程（全书最关键）、KV Cache、提示工程</td><td><a href="./02-chapter2.html">02-chapter2.md</a></td></tr><tr><td><strong>构建</strong></td><td>第三章</td><td>用户记忆、知识库、RAG 技术</td><td><a href="./03-chapter3.html">03-chapter3.md</a></td></tr><tr><td><strong>构建</strong></td><td>第四章</td><td>工具设计、MCP 协议、安全机制</td><td><a href="./04-chapter4.html">04-chapter4.md</a></td></tr><tr><td><strong>构建</strong></td><td>第五章</td><td>Coding Agent、代码生成、OpenClaw 架构</td><td><a href="./05-chapter5.html">05-chapter5.md</a></td></tr><tr><td><strong>评估</strong></td><td>第六章</td><td>Agent 评估、数据集设计、LLM-as-a-Judge</td><td><a href="./06-chapter6.html">06-chapter6.md</a></td></tr><tr><td><strong>评估</strong></td><td>第七章</td><td>模型后训练、SFT vs RL、奖励信号设计</td><td><a href="./07-chapter7.html">07-chapter7.md</a></td></tr><tr><td><strong>进化</strong></td><td>第八章</td><td>持续进化、四种更新载体、闭环机制</td><td><a href="./08-chapter8.html">08-chapter8.md</a></td></tr><tr><td><strong>扩展</strong></td><td>第九章</td><td>多模态交互、语音 Agent、Computer Use</td><td><a href="./09-chapter9.html">09-chapter9.md</a></td></tr><tr><td><strong>扩展</strong></td><td>第十章</td><td>多 Agent 协作、协作框架、Agent 社会</td><td><a href="./10-chapter10.html">10-chapter10.md</a></td></tr><tr><td><strong>总结</strong></td><td>后记</td><td>两朵乌云、核心挑战、未来展望</td><td><a href="./11-afterword.html">11-afterword.md</a></td></tr></tbody></table><hr><h2 id="核心观点速查" tabindex="-1">核心观点速查 <a class="header-anchor" href="#核心观点速查" aria-label="Permalink to &quot;核心观点速查&quot;">​</a></h2><h3 id="_1-架构原则" tabindex="-1">1. 架构原则 <a class="header-anchor" href="#_1-架构原则" aria-label="Permalink to &quot;1. 架构原则&quot;">​</a></h3><table tabindex="0"><thead><tr><th>原则</th><th>说明</th></tr></thead><tbody><tr><td><strong>实践在前，命名在后</strong></td><td>架构概念来自实践总结，不是先有名词才有实践</td></tr><tr><td><strong>好的设计原则穿越模型迭代周期</strong></td><td>原则描述的是智能系统与世界交互的基本模式</td></tr><tr><td><strong>没有评估，就没有进步</strong></td><td>评估是科学方法论的地基</td></tr></tbody></table><h3 id="_2-训练方法" tabindex="-1">2. 训练方法 <a class="header-anchor" href="#_2-训练方法" aria-label="Permalink to &quot;2. 训练方法&quot;">​</a></h3><table tabindex="0"><thead><tr><th>论点</th><th>说明</th></tr></thead><tbody><tr><td><strong>SFT 记忆，RL 泛化</strong></td><td>SFT 学会固定映射，RL 学会可迁移策略</td></tr><tr><td><strong>数据与环境比算法更重要</strong></td><td>算法够用就行，真正拉开差距的是数据和仿真环境</td></tr><tr><td><strong>先形后神</strong></td><td>SFT 先稳定格式，RL 再塑形策略</td></tr></tbody></table><h3 id="_3-技术基础" tabindex="-1">3. 技术基础 <a class="header-anchor" href="#_3-技术基础" aria-label="Permalink to &quot;3. 技术基础&quot;">​</a></h3><table tabindex="0"><thead><tr><th>基础</th><th>说明</th></tr></thead><tbody><tr><td><strong>Coding Agent + 文件系统</strong></td><td>通用 Agent 的核心技术基础</td></tr><tr><td><strong>上下文决定能力上限</strong></td><td>Agent 能看到什么决定了它能做什么</td></tr><tr><td><strong>Harness 工程决定可靠性</strong></td><td>模型能力商品化，竞争优势在模型之外的工程实践</td></tr></tbody></table><hr><h2 id="关键技术栈" tabindex="-1">关键技术栈 <a class="header-anchor" href="#关键技术栈" aria-label="Permalink to &quot;关键技术栈&quot;">​</a></h2><table tabindex="0"><thead><tr><th>领域</th><th>技术</th><th>章节</th></tr></thead><tbody><tr><td>上下文管理</td><td>KV Cache、Prompt Cache、上下文压缩</td><td>第二章</td></tr><tr><td>知识检索</td><td>RAG、Agentic RAG、混合检索</td><td>第三章</td></tr><tr><td>工具交互</td><td>MCP、Skills 按需加载、状态栏</td><td>第四章</td></tr><tr><td>代码生成</td><td>OpenClaw、Harness、沙盒隔离</td><td>第五章</td></tr><tr><td>评估方法</td><td>Benchmark、LLM-as-a-Judge、统计显著性</td><td>第六章</td></tr><tr><td>后训练</td><td>SFT、RLHF、PPO/GRPO/DPO</td><td>第七章</td></tr><tr><td>持续进化</td><td>四种更新载体、灰度发布、回滚</td><td>第八章</td></tr><tr><td>多模态</td><td>语音 Agent、Computer Use、VLA</td><td>第九章</td></tr><tr><td>多 Agent</td><td>协作框架、通信机制、Agent 社会</td><td>第十章</td></tr></tbody></table><hr><h2 id="实验清单" tabindex="-1">实验清单 <a class="header-anchor" href="#实验清单" aria-label="Permalink to &quot;实验清单&quot;">​</a></h2><p>每章配套实验（详见原书）：</p><table tabindex="0"><thead><tr><th>章节</th><th>实验主题</th></tr></thead><tbody><tr><td>第一章</td><td>ReAct 循环、工具调用轨迹分析</td></tr><tr><td>第二章</td><td>KV Cache 原理、提示注入攻防、上下文压缩</td></tr><tr><td>第三章</td><td>记忆系统设计、RAG 检索优化、多模态提取</td></tr><tr><td>第四章</td><td>MCP 工具开发、安全机制实现、事件驱动架构</td></tr><tr><td>第五章</td><td>Coding Agent 实现、Harness 工程</td></tr><tr><td>第六章</td><td>评估环境搭建、Benchmark 分析</td></tr><tr><td>第七章</td><td>SFT 微调、RLHF 训练、GRPO 实现</td></tr><tr><td>第八章</td><td>持续进化闭环、灰度发布</td></tr><tr><td>第九章</td><td>语音 Agent、Computer Use</td></tr><tr><td>第十章</td><td>多 Agent 协作、Agent 社会</td></tr></tbody></table><p><strong>配套代码仓库</strong>：<a href="https://github.com/bojieli/ai-agent-book" target="_blank" rel="noreferrer">https://github.com/bojieli/ai-agent-book</a></p><hr><h2 id="阅读路径建议" tabindex="-1">阅读路径建议 <a class="header-anchor" href="#阅读路径建议" aria-label="Permalink to &quot;阅读路径建议&quot;">​</a></h2><table tabindex="0"><thead><tr><th>角色</th><th>建议路径</th></tr></thead><tbody><tr><td><strong>Agent 开发者</strong></td><td>第一至八章顺序阅读</td></tr><tr><td><strong>时间有限者</strong></td><td>第一章 + 第二章（最关键）</td></tr><tr><td><strong>关注模型训练</strong></td><td>第六章 + 第七章</td></tr><tr><td><strong>关注多模态/协作</strong></td><td>第九章 + 第十章</td></tr></tbody></table><hr><h2 id="前置知识" tabindex="-1">前置知识 <a class="header-anchor" href="#前置知识" aria-label="Permalink to &quot;前置知识&quot;">​</a></h2><p><strong>必需</strong>：</p><ul><li>Python 编程基础</li><li>LLM 基本使用经验</li><li>AI 辅助编程工具（Claude Code、Cursor 等）</li><li>软件工程常识（命令行、Git、JSON、REST API）</li></ul><p><strong>推荐（特定章节）</strong>：</p><ul><li>机器学习基础（第七章）</li><li>基础数学：线性代数、概率统计（第 2-3、7 章）</li><li>Web 开发基础（第 4、9 章）</li><li>Transformer 架构理解（第 2、7 章）</li></ul><hr><h2 id="核心挑战-两朵乌云" tabindex="-1">核心挑战（两朵乌云） <a class="header-anchor" href="#核心挑战-两朵乌云" aria-label="Permalink to &quot;核心挑战（两朵乌云）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>挑战</th><th>解决路径</th></tr></thead><tbody><tr><td><strong>实时交互</strong></td><td>快慢分离架构 / 推理加速</td></tr><tr><td><strong>持续学习</strong></td><td>经验转化为知识/指令/程序/参数更新</td></tr></tbody></table><hr><p><strong>笔记整理时间</strong>：2026年7月31日 <strong>原文总字数</strong>：约90万字 <strong>笔记总字数</strong>：约12万字</p>',39)])])}const p=d(o,[["render",h]]);export{c as __pageData,p as default};
